expansions.content:
// A report on a repository with no Go code, no API, and no migrations says
// nothing about coverage, the API, or migrations. Naming those absences tells
// the reader nothing they did not know and buries the panes that did apply
// and could not run.
func TestWhatDoesNotApplyIsNotMentioned(t *testing.T) {
	rep := &findings.Report{
		Coverage: findings.Coverage{ChangedFiles: 1, ExaminedFiles: 1},
		Substrates: []findings.SubstrateStatus{
			{Name: "migrations", State: findings.SubstrateNotApplicable, Detail: "the repository has no files this pane reads"},
			{Name: "openapi", State: findings.SubstrateNotApplicable, Detail: "the repository has no files this pane reads"},
			{Name: "lint", State: findings.SubstrateSkipped, Detail: "this change touches none of the files this pane reads"},
		},
	}
	ch := &change.Set{Files: []change.File{{Path: "README.md", Areas: []string{"docs"}}}}

	html, err := HTML(HTMLInput{Report: rep, Change: ch})
	if err != nil {
		t.Fatal(err)
	}
	for _, absent := range []string{
		`id="coverage"`, "No coverage profile was found", "diff covered",
		`id="interface"`,
		"<code>migrations</code>", "<code>openapi</code>",
	} {
		if strings.Contains(html, absent) {
			t.Errorf("page must not mention %q for a change it does not apply to", absent)
		}
	}
	// The pane the repository does have, that this change did not reach, is
	// still listed, folded away.
	if !strings.Contains(html, "1 pane did not apply") || !strings.Contains(html, "<code>lint</code>") {
		t.Error("a pane the repository has but the change did not touch is still listed")
	}

	md := Markdown(rep, nil, nil, ch)
	for _, absent := range []string{"## Coverage", "No coverage profile", "`migrations`", "`openapi`"} {
		if strings.Contains(md, absent) {
			t.Errorf("markdown must not mention %q", absent)
		}
	}
	if !strings.Contains(md, "1 pane(s) did not apply to this change") || !strings.Contains(md, "`lint`") {
		t.Error("markdown still lists the pane the change did not touch")
	}
}

// Run executes every applicable pane. Applicability is computed from the diff,
// never chosen by a caller: if the caller decides which checks to run, coverage
// becomes a sample from a distribution and a check can be silently skipped.
func Run(opts Options) (*Result, error) {
	tgt, err := target.Resolve(target.Options{
		Dir: opts.Dir, PR: opts.PR, Branch: opts.Branch,
		Commit: opts.Commit, Range: opts.Range, Base: opts.Base,
	})
	if err != nil {
		return nil, err
	}
	// Panes observe the target's directory. For a PR or a branch that is a
	// detached worktree at the head commit, so "the working tree" and "the
	// revision under review" are the same thing and no pane needs to know
	// which kind of target it is looking at.
	repo, err := gitx.Open(tgt.Dir)
	if err != nil {
		return nil, err
	}
	if tgt.Base != "" {
		opts.Base = tgt.Base
	}
	baseRef := resolveRef(repo, opts.Base)
	if baseRef == "" {
		return nil, fmt.Errorf("cannot determine a base revision: tried %s. "+
			"Pass --base REF, or make a first commit if this repository has none",
			strings.Join(defaultRefs, ", "))
	}
	baseSHA, err := repo.MergeBase(baseRef)
	if err != nil {
		return nil, fmt.Errorf("base %q: %w", baseRef, err)
	}
	changed, err := repo.ChangedPaths(baseSHA)
	if err != nil {
		return nil, err
	}
	changed = excludeOwnOutput(changed, opts.Out, repo.Root)

	// Generated output leaves the change here, before any pane or the report
	// sees it, so the coverage denominator counts files a reviewer would
	// actually read. What was dropped is recorded and shown: an exclusion the
	// reader cannot see is indistinguishable from a file that never changed.
	changed, generated := change.Generated(tgt.Dir, changed, repo.AttrSet("linguist-generated", changed))

	res := &Result{Evidence: map[string]pane.Artifact{}, Target: tgt, Report: findings.Report{
		BaseRef: baseRef,
		BaseSHA: baseSHA,
		Scope:   changed,
	}}

	panes := []pane.Pane{
		&migrations.Pane{Repo: repo, UpstreamRef: resolveRef(repo, opts.Upstream, baseRef), Dir: opts.MigDir},
		&openapi.Pane{Repo: repo},
		&lint.Delta{Repo: repo},
		&lint.Suppressions{Repo: repo},
		&lint.Config{Repo: repo},
	}

	// Every path in the tree under review, listed once and only if a pane
	// turns out to have nothing in the change to look at. It answers a
	// different question from scope: not "does this pane apply to the change"
	// but "does this pane apply to the repository". A repository with no
	// migrations gets no mention of migrations; one whose migrations this
	// change did not touch is told so, quietly.
	var allPaths []string
	listAll := func() []string {
		if allPaths != nil {
			return allPaths
		}
		var blobs map[string]string
		var lerr error
		if tgt.Head == "" {
			blobs, lerr = repo.WorktreeBlobs()
		} else {
			blobs, lerr = repo.Blobs(tgt.Head)
		}
		if lerr != nil {
			// Unknown whether the pane applies: fall back to saying it was
			// skipped, the state that still gets a line on the report.
			allPaths = []string{}
			return allPaths
		}
		allPaths = make([]string, 0, len(blobs))
		for path := range blobs {
			allPaths = append(allPaths, path)
		}
		sort.Strings(allPaths)
		return allPaths
	}

	examined := map[string]bool{}
	for _, p := range panes {
		status := findings.SubstrateStatus{Name: p.Name()}
		scope := p.Scope(changed)
		for _, path := range scope {
			examined[path] = true
		}
		if len(scope) == 0 {
			// Scope over the whole tree is only consulted for a pane that will
			// not run, so the state it leaves behind in the pane is unused.
			if all := listAll(); len(all) > 0 && len(p.Scope(all)) == 0 {
				status.State = findings.SubstrateNotApplicable
				status.Detail = "the repository has no files this pane reads"
			} else {
				status.State = findings.SubstrateSkipped
				status.Detail = "this change touches none of the files this pane reads"
			}
			res.Report.Substrates = append(res.Report.Substrates, status)
			continue
		}
		out, err := runPane(p, baseSHA)
		if err != nil {
			// A pane that applied but did not run is recorded as failed and
			// as an unknown; it never reads as a pass.
			status.State = findings.SubstrateFailed
			status.Detail = err.Error()
			res.Report.Substrates = append(res.Report.Substrates, status)
			res.Report.Unknowns = append(res.Report.Unknowns, findings.Unknown{
				Substrate: p.Name(),
				Message:   "pane applied to this change but did not run",
				Reason:    err.Error(),
			})
			continue
		}
		status.State = findings.SubstrateRan
		res.Report.Substrates = append(res.Report.Substrates, status)
		res.Report.Findings = append(res.Report.Findings, out.Findings...)
		res.Report.Confirmations = append(res.Report.Confirmations, out.Confirmations...)
		res.Report.Unknowns = append(res.Report.Unknowns, out.Unknowns...)
		res.Renders = append(res.Renders, out.Render)
		for id, a := range out.Evidence {
			res.Evidence[id] = a
		}
	}

	res.Report.Coverage = coverage(changed, examined)
	res.Report.Coverage.Generated = generated
	res.Report.Unknowns = append(res.Report.Unknowns, unbuiltPanes(changed, examined)...)
	// The agent's review, if it has written one. Loaded before Finalize so its
	// line comments become findings that get fingerprints stamped with the rest;
	// verdicts merge after, joining on those fingerprints. Never fatal: a run
	// reports facts with or without a reading, and a broken file is stated.
	review, verr := findings.LoadReview(filepath.Join(opts.Out, "review.json"))
	if verr != nil {
		res.Report.Unknowns = append(res.Report.Unknowns, findings.Unknown{
			Substrate: "redline/review",
			Message:   "review.json was present but could not be read, so no agent review was merged",
			Reason:    verr.Error(),
		})
	}
	if review != nil {
		res.Report.Findings = append(res.Report.Findings, review.CommentFindings()...)
		if review.Overview != "" || len(review.Files) > 0 {
			res.Report.Agent = &findings.AgentReview{Overview: review.Overview, Files: review.Files}
		}
	}
	if res.Report.Coverage.ExaminedFiles == 0 && len(changed) > 0 {
		// No pane looked at any of it. This is not a clean review and must
		// never render as one. Stated after the agent's comments merge, so
		// the reason can be honest about whether the findings list is empty.
		reason := "this change is entirely unexamined; the empty findings list below is not evidence of correctness"
		if len(res.Report.Findings) > 0 {
			reason = "no pane covers these files; the findings below come from the agent's review"
		}
		res.Report.Unknowns = append(res.Report.Unknowns, findings.Unknown{
			Substrate: "redline",
			Message:   fmt.Sprintf("none of the %d changed file(s) fall under any pane Redline currently ships", len(changed)),
			Reason:    reason,
		})
	}
	res.Report.Finalize()
	if review != nil {
		res.Report.MergeVerdicts(review.Verdicts)
	}
	findings.Sort(res.Report.Findings)

	res.Change = change.Build(repo, tgt, baseSHA, changed)
	covDir := originCoverageDir(opts.Dir, tgt)
	attachDiffCoverage(&res.Report, res.Change, tgt.Dir, covDir)
	res.LineCoverage = lineCoverageOverlay(tgt.Dir, covDir, res.Change)
	return res, nil
}

// A repository with no migrations and no API spec is not told that its
// migrations and API went unexamined. The pane is recorded as not applicable,
// which no renderer mentions, rather than skipped, which they list.
func TestPaneNotApplicableWhenRepositoryHasNoSuchFiles(t *testing.T) {
	r := newRepo(t)
	r.write("main.go", "package main\n")
	r.commit("init")
	r.git("checkout", "-b", "feature")
	r.write("main.go", "package main\n\nfunc main() {}\n")

	rep := r.run(run.Options{Base: "main"}).Report
	states := map[string]findings.SubstrateState{}
	for _, s := range rep.Substrates {
		states[s.Name] = s.State
	}
	for _, name := range []string{"redline/sql", "redline/api"} {
		if states[name] != findings.SubstrateNotApplicable {
			t.Errorf("%s: expected not-applicable in a repository with no such files, got %q", name, states[name])
		}
	}
	if rep.Coverage.CoverableFiles != 1 {
		t.Errorf("one Go file changed, coverableFiles = %d", rep.Coverage.CoverableFiles)
	}
	md := report.Markdown(&rep, nil, nil, nil)
	if strings.Contains(md, "redline/sql") || strings.Contains(md, "redline/api") {
		t.Errorf("the markdown report must not mention panes the repository has no files for:\n%s", md)
	}
}

// The same repository, with the change touching only a docs file: nothing is
// coverable, so coverage is left out rather than reported as unmeasured.
func TestCoverageNotMentionedWhenNothingIsCoverable(t *testing.T) {
	r := newRepo(t)
	r.write("README.md", "# hi\n")
	r.commit("init")
	r.git("checkout", "-b", "feature")
	r.write("README.md", "# hi\n\nmore\n")

	res := r.run(run.Options{Base: "main"})
	if res.Report.Coverage.CoverableFiles != 0 || res.Report.Coverage.Diff != nil {
		t.Fatalf("nothing coverable: %+v", res.Report.Coverage)
	}
	for _, u := range res.Report.Unknowns {
		if u.Substrate == "redline/tests" {
			t.Errorf("no coverage unknown should be raised for a change with no coverable file: %+v", u)
		}
	}
	md := report.Markdown(&res.Report, res.Renders, res.Evidence, res.Change)
	if strings.Contains(md, "coverage") {
		t.Errorf("markdown must not mention coverage:\n%s", md)
	}
}

// A pane the repository has no files for gets no row: the table accounts for
// the checks that could have run, and "no linter is configured" is not one.
// The same for coverage on a change with nothing a profile could cover.
func TestBuildBodyOmitsWhatDoesNotApply(t *testing.T) {
	rep := sampleReport()
	if p := Build(rep, prTarget(), "", nil); strings.Contains(p.Body, "| lint |") {
		t.Fatalf("a not-applicable pane must not get a row:\n%s", p.Body)
	}
	rep.Coverage.CoverableFiles = 0
	if p := Build(rep, prTarget(), "", nil); strings.Contains(p.Body, "diff coverage") {
		t.Fatalf("coverage must not be mentioned when no changed file is coverable:\n%s", p.Body)
	}
}

// Coverage records how much of the change Redline actually examined. It is
// the answer to the question a reader of an empty report cannot otherwise ask:
// did every check come back clean, or did nothing look? Without it a report
// covering none of a change is indistinguishable from one covering all of it.
type Coverage struct {
	ChangedFiles  int      `json:"changedFiles"`
	ExaminedFiles int      `json:"examinedFiles"`
	Unexamined    []string `json:"unexamined,omitempty"`

	// Generated are paths dropped from the change as machine output before any
	// pane ran. They are listed rather than merely counted: excluding a file a
	// human actually wrote is the one way this feature can hide a real change,
	// and naming every exclusion is what makes that recoverable.
	Generated []string `json:"generated,omitempty"`

	// CoverableFiles counts the changed files a coverage profile could
	// describe (Go files, until the pane reads other formats). Zero means the
	// coverage number does not apply to this change, and the report leaves
	// coverage out entirely rather than reporting a profile as missing for a
	// change no profile could ever cover.
	CoverableFiles int `json:"coverableFiles"`

	// Diff is the share of added lines a test profile shows executed. Nil when
	// no profile was found, which must render as "nobody knows" rather than as
	// zero per cent — those are very different claims. Only meaningful when
	// CoverableFiles is non-zero.
	Diff *cover.Result `json:"diffCoverage,omitempty"`
}

// SubstrateNotApplicable is a pane the repository has no files for at all:
// no migrations, no API spec, no linter configured. It is recorded here so
// findings.json says the pane exists, and rendered nowhere. A report on a
// repository with no API should not mention the API; naming an absence
// the reader already knows about is noise, and worse, it makes the panes
// that did apply and failed harder to see.
SubstrateNotApplicable SubstrateState = "not-applicable"

// CoverageApplies reports whether the coverage number has anything to say
// about this change: a profile was read, or a changed file could have been
// covered by one. When false, coverage is left off the report.
func (c Coverage) CoverageApplies() bool {
	return c.Diff != nil || c.CoverableFiles > 0
}

// UI capture is not built. Its absence is stated in proportion to whether the
// interface actually moved.
func TestInterfaceSectionIsHonestWhenEmpty(t *testing.T) {
	uiChange := &change.Set{
		UITouched: true,
		Files:     []change.File{{Path: "web/src/App.tsx", Areas: []string{"ui"}}},
	}
	rep := &findings.Report{Coverage: findings.Coverage{ChangedFiles: 1, ExaminedFiles: 0}}

	html, err := HTML(HTMLInput{Report: rep, Change: uiChange})
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(html, "touches the interface and no routes were captured") {
		t.Error("a UI change with no captures must read as a gap")
	}
	// Loud, not a footnote.
	if !strings.Contains(html, `<div class="banner">This change touches the interface`) {
		t.Error("that gap belongs in a banner, not italic small print")
	}

	noUI := &change.Set{Files: []change.File{{Path: "a.go", Areas: []string{"code"}}}}
	html, err = HTML(HTMLInput{Report: rep, Change: noUI})
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(html, "touches the interface and no routes were captured") {
		t.Error("a change with no UI files must not claim a UI gap")
	}
	if strings.Contains(html, `id="interface"`) {
		t.Error("a change with no UI files gets no interface section: there is nothing to say")
	}
}

// The sidebar should show where the gaps are without scrolling to find them.
func TestNavMarksSectionsThatAreGaps(t *testing.T) {
	html, err := HTML(HTMLInput{
		// UI moved with nothing captured, and a coverable file with no profile.
		Report: &findings.Report{
			Coverage: findings.Coverage{ChangedFiles: 1, ExaminedFiles: 0, CoverableFiles: 1},
			Unknowns: []findings.Unknown{{Substrate: "s", Message: "u"}},
		},
		Change: &change.Set{
			UITouched: true,
			Files:     []change.File{{Path: "web/src/App.tsx", Areas: []string{"ui"}}},
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	for _, id := range []string{"interface", "coverage", "unknowns"} {
		re := regexp.MustCompile(`data-nav="` + id + `"[^>]*class="gap"`)
		if !re.MatchString(html) {
			t.Errorf("%s should be marked as a gap in the sidebar", id)
		}
	}
	// A section with a real result is not a gap.
	if regexp.MustCompile(`data-nav="drill"[^>]*class="gap"`).MatchString(html) {
		t.Error("the drill-in file list is not a gap")
	}
}

// The number stands in for reading the tests, so its absence has to be as
// legible as its presence. A missing profile rendering as 0% would read as
// "nothing is tested", which is a much stronger claim than "nobody measured".
func TestMissingCoverageProfileReadsAsUnknownNotZero(t *testing.T) {
	rep := &findings.Report{Coverage: findings.Coverage{ChangedFiles: 1, ExaminedFiles: 1, CoverableFiles: 1}}
	ch := &change.Set{Files: []change.File{{Path: "a.go", Areas: []string{"code"}}}}

	html, err := HTML(HTMLInput{Report: rep, Change: ch})
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(html, "No coverage profile was found") {
		t.Error("the page must say the number is unknown")
	}
	if !strings.Contains(html, "not the same as untested") {
		t.Error("the page must distinguish unmeasured from untested")
	}
	if strings.Contains(html, "% of the") {
		t.Error("a missing profile must never render as a percentage")
	}
	// The tile reads as unanswered rather than as a score.
	if !strings.Contains(html, `<div class="n warning">?</div><div class="l">diff covered</div>`) {
		t.Error("the coverage tile must show ? when nothing measured it")
	}

	md := Markdown(rep, nil, nil, ch)
	if !strings.Contains(md, "No coverage profile was found") {
		t.Error("markdown must say the same")
	}
}

// navFor lists the sections this page will render, in page order. It must stay
// in step with the template: TestNavMatchesTheSectionsOnThePage fails if a
// section gains or loses a heading without its entry moving too.
func navFor(v view) []navLink {
	// A UI that moved with nothing captured is a gap; a change with no UI files
	// has no interface section. Coverage is the same: a change with no
	// coverable file has no coverage section, and one with a coverable file
	// and no profile is a gap.
	coverageGap := v.Coverage.Diff == nil || v.Coverage.Diff.Stale

	nav := []navLink{}
	if v.Overview != "" {
		nav = append(nav, navLink{ID: "review", Label: "Review"})
	}
	if v.UITouched {
		nav = append(nav, navLink{ID: "interface", Label: "What it looks like", Warn: true})
	}
	if v.Coverage.CoverageApplies() {
		nav = append(nav, navLink{ID: "coverage", Label: "Coverage", Warn: coverageGap})
	}
	if len(v.Groups) > 0 {
		nav = append(nav, navLink{ID: "drill", Label: "Drill in", Count: len(v.Groups)})
	}
	if len(v.Renders) > 0 {
		nav = append(nav, navLink{ID: "changed", Label: "What changed", Count: len(v.Renders)})
	}
	nav = append(nav, navLink{ID: "observed", Label: "What Redline observed", Count: len(v.Observed)})
	nav = append(nav,
		navLink{ID: "unknowns", Label: "Undetermined", Count: len(v.Unknowns) + len(v.Failed), Warn: len(v.Unknowns)+len(v.Failed) > 0},
		navLink{ID: "confirms", Label: "Checked and held", Count: len(v.Confirms)},
	)
	return nav
}

// evidenceTable is the one-line-per-pane account of what was checked. It is
// what makes the posted review verifiable in scope: a pane that did not run is
// named here, where a reader of the pull request will actually see it.
func evidenceTable(rep *findings.Report) string {
	if rep == nil {
		return ""
	}
	perSubstrate := map[string]int{}
	for _, f := range rep.Findings {
		perSubstrate[f.Substrate]++
	}
	var b strings.Builder
	b.WriteString("| Evidence | Result |\n|---|---|\n")
	for _, s := range rep.Substrates {
		var result string
		switch s.State {
		case findings.SubstrateRan:
			result = fmt.Sprintf("ran — %d finding(s)", perSubstrate[s.Name])
		case findings.SubstrateSkipped:
			result = "did not apply"
		case findings.SubstrateNotApplicable:
			// The repository has no such files; the row would only say so.
			continue
		default:
			result = fmt.Sprintf("**did not run** — %s", escapeCell(s.Detail))
		}
		fmt.Fprintf(&b, "| %s | %s |\n", escapeCell(s.Name), result)
	}
	if c := rep.Coverage.Diff; c != nil {
		switch {
		case c.Percent < 0:
			fmt.Fprintf(&b, "| diff coverage | no coverable added line (`%s`) |\n", c.Profile)
		case c.Stale:
			fmt.Fprintf(&b, "| diff coverage | %.0f%% of %d added line(s), from a stale `%s` |\n", c.Percent, c.Lines, c.Profile)
		default:
			fmt.Fprintf(&b, "| diff coverage | %.0f%% of %d added line(s) (`%s`) |\n", c.Percent, c.Lines, c.Profile)
		}
	} else if rep.Coverage.CoverableFiles > 0 {
		b.WriteString("| diff coverage | not measured — no profile found |\n")
	}
	fmt.Fprintf(&b, "| files examined | %d/%d |\n", rep.Coverage.ExaminedFiles, rep.Coverage.ChangedFiles)
	return b.String()
}

// coverageSection is the number that stands in for reading the tests. An
// absent profile is stated as absent: "no test executes these lines" and
// "nobody measured" are different claims and only one is the author's problem.
// A change no profile could describe gets no section at all.
func coverageSection(b *strings.Builder, rep *findings.Report) {
	if !rep.Coverage.CoverageApplies() {
		return
	}
	fmt.Fprintf(b, "## Coverage\n\n")
	c := rep.Coverage.Diff
	if c == nil {
		fmt.Fprintf(b, "_No coverage profile was found, so whether these changes are tested is unknown. "+
			"That is not the same as untested — run the suite with `-coverprofile=coverage.out`._\n\n")
		return
	}
	if c.Stale {
		fmt.Fprintf(b, "> **The profile `%s` predates this change**, so its number does not describe "+
			"the code under review. Re-run the suite with `-coverprofile`.\n\n", c.Profile)
	}
	if c.Percent < 0 {
		fmt.Fprintf(b, "No added line is coverable, so there is nothing for a test to execute (`%s`).\n\n", c.Profile)
	} else {
		fmt.Fprintf(b, "**%.0f%%** of the %d coverable line(s) this change adds are executed by a test, "+
			"according to `%s`. %d covered, %d not.\n\n",
			c.Percent, c.Lines, c.Profile, c.Covered, c.Lines-c.Covered)
	}
	if c.TotalPercent >= 0 {
		fmt.Fprintf(b, "Repository-wide, **%.0f%%** of %d coverable line(s) in `%s` are covered "+
			"(%d covered, %d not) — the profile's whole scope, not just what this change added.\n\n",
			c.TotalPercent, c.TotalLines, c.Profile, c.TotalCovered, c.TotalLines-c.TotalCovered)
	}
	for _, gap := range c.Uncovered {
		fmt.Fprintf(b, "- `%s` — %d uncovered added line(s)\n", gap.Path, len(gap.Lines))
	}
	if len(c.Uncovered) > 0 {
		fmt.Fprintln(b)
	}
}

func sampleReport() *findings.Report {
	rep := &findings.Report{
		Coverage: findings.Coverage{ChangedFiles: 5, ExaminedFiles: 3, CoverableFiles: 2},
		Substrates: []findings.SubstrateStatus{
			{Name: "migrations", State: findings.SubstrateRan},
			{Name: "openapi", State: findings.SubstrateSkipped, Detail: "this change touches none of the files this pane reads"},
			{Name: "lint", State: findings.SubstrateNotApplicable, Detail: "the repository has no files this pane reads"},
		},
		Findings: []findings.Finding{
			{File: "a.go", Line: 12, Rule: "migration-modified-after-merge", Substrate: "migrations",
				Severity: findings.SeverityError, Message: "merged migration edited"},
			{Rule: "migration-edited", Substrate: "redline/sql",
				Severity: findings.SeverityWarning, Message: "migration edited after merge"},
		},
	}
	rep.Finalize()
	return rep
}

// view is the flattened shape the template consumes.
type view struct {
	Title    string
	Subtitle string
	URL      string
	Author   string
	Coverage findings.Coverage
	Banner   string
	Counts   map[string]int

	// Overview is the agent's summary of the change, from review.json. Empty
	// when the agent wrote none; the Review section and its nav entry render
	// only when it is present.
	Overview string

	// Renders is what changed, in the domain where it lives — a pane's own
	// account (e.g. the lint delta's introduced/resolved count, or a
	// suppression's added-directive list), not a finding. Markdown has
	// rendered this since section1 existed; HTML dropped it on the floor
	// until a report with a real lint delta and no visible "Lint" anywhere
	// on the page exposed the gap.
	Renders []pane.Render

	// DiffFiles is the deduped set of changed files that appear in a drill-in
	// area, each with its diff. Rendered once into a hidden store the drawer
	// moves from, so a diff exists in exactly one place in the DOM.
	DiffFiles []fileView
	Observed  []findingView

	Groups   []drillGroup
	Confirms []findings.Confirmation
	Unknowns []findings.Unknown
	Failed   []findings.SubstrateStatus
	Skipped  []findings.SubstrateStatus
	// UITouched is whether the change moves the interface at all. A change
	// that touches no UI gets no interface section; on one that does, the
	// absence of captures is a gap and is said so.
	UITouched bool
	// Nav is the sidebar: one entry per section actually rendered, in the order
	// they appear. Built here rather than scanned out of the DOM so the page
	// has a map before any script runs.
	Nav []navLink

	Commits int
	// Identity keys browser-local comments to this review, not to the
	// report.html path — every run overwrites the same file.
	Identity string
}

// attachDiffCoverage computes the number that stands in for reading the tests.
// It needs the per-file diffs, so it runs after change.Build.
//
// A missing profile is recorded as an unknown. This is the whole point of the
// number: "no test executes these lines" and "nobody measured" look identical on
// a page that only shows a percentage, and only one of them is a problem the
// author can fix by writing a test.
func attachDiffCoverage(rep *findings.Report, ch *change.Set, dir, originDir string) {
	if ch == nil || len(ch.Files) == 0 {
		return
	}
	changed := make([]cover.Changed, 0, len(ch.Files))
	goFiles := 0
	for _, f := range ch.Files {
		if filepath.Ext(f.Path) != ".go" {
			continue
		}
		goFiles++
		changed = append(changed, cover.Changed{Path: f.Path, Added: cover.AddedLines(f.Diff)})
	}
	rep.Coverage.CoverableFiles = goFiles
	if goFiles == 0 {
		return
	}
	rep.Coverage.Diff = cover.Compute(dir, changed)
	if rep.Coverage.Diff == nil && originDir != "" && originDir != dir {
		// The panes observe a pristine worktree of the reviewed revision, which
		// holds no local coverage profile. When that revision is the origin
		// checkout's own HEAD, the developer's profile there describes exactly
		// this code, so read it instead of reporting the tests as unmeasured.
		rep.Coverage.Diff = cover.Compute(originDir, changed)
	}
	switch {
	case rep.Coverage.Diff == nil:
		rep.Unknowns = append(rep.Unknowns, findings.Unknown{
			Substrate: "redline/tests",
			Message:   fmt.Sprintf("no coverage profile was found, so whether any test executes the %d changed Go file(s) is unknown", goFiles),
			Reason:    "looked for coverage.out, cover.out, coverage.txt and c.out; run the suite with -coverprofile to get this number",
		})
	case rep.Coverage.Diff.Stale:
		rep.Unknowns = append(rep.Unknowns, findings.Unknown{
			Substrate: "redline/tests",
			Message:   fmt.Sprintf("the coverage profile %s is older than a file in this change, so its number does not describe the code under review", rep.Coverage.Diff.Profile),
			Reason:    "re-run the suite with -coverprofile",
		})
	}
}

		return nil, err
	}
	return run.Run(o.toRun(cwd))
}

